tabPos = "1";
$(function() {
    $("input.date").datepicker({
        /* 날짜1, 한국어 */
        showOn: "button",
        buttonImage: "../img/ods/ic_cal.png",
        buttonImageOnly: true,
        buttonText: "Select date",
        dateFormat: 'yy-mm-dd',
        prevText: '이전 달',
        nextText: '다음 달',
        changeMonth: true,
        changeYear: true,
        monthNames: ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'],
        monthNamesShort: ['1월', '2월', '3월', '4월', '5월', '6월', '7월', '8월', '9월', '10월', '11월', '12월'],
        dayNames: ['일', '월', '화', '수', '목', '금', '토'],
        dayNamesShort: ['일', '월', '화', '수', '목', '금', '토'],
        dayNamesMin: ['일', '월', '화', '수', '목', '금', '토'],
        showMonthAfterYear: true,
        yearSuffix: '년'
    });
    $('.table_v').each(function(i) {
        $(this).find('tbody tr:odd').addClass('bgcolor');
    });
    /**
     * @method
     * @name tabs
     * @description desc
     * @param {string} tab desc
     * @param {string} tabcont desc
     * @returns
     * @hidden N
     * @exception
     * @example
     */
    function tabs(tab, tabcont) {
        /**
         * @method
         * @name tabcont
         * @description desc
         * @param
         * @returns
         * @hidden N
         * @exception
         * @example
         */
        function tabcont() {
            $(tab).each(function() {
                var link = $(this).find('a').attr('href');
                $(link).hide();
            });
        };
        tabcont();
        $($(tab).first().find('a').attr('href')).show();
        $(tab).first().addClass('active');
        $(tab).find('a').on('click', function() {
            if ($('#integSrchNo').val().length == 0) {
                alert("저장후 이동가능 합니다.");
                return;
            }
            if (scwin.tabPos == "2" && chkMod()) {
                if (confirm("변경된 업무해설이 있습니다. 저장하시겠습니까?")) {
                    fn_regExpls("move");
                }
            }
            if (!$(this).parent().hasClass('active')) {
                var link = $(this).attr('href');
                $(tab).removeClass();
                $(this).parent().addClass('active');
                tabcont();
                $(link).fadeIn();
                if ($(link).selector == '#search_tab1') {
                    $('#pageIndex').val("1");
                    fn_searchKeywrdListDtl();
                    scwin.tabPos = "1";
                }
                if ($(link).selector == '#search_tab2') {
                    fn_openExpl();
                    scwin.tabPos = "2";
                }
                if ($(link).selector == '#search_tab3') {
                    $('#pageIndex').val("1");
                    fn_openRelLaw();
                    fn_searchRelLawDtl();
                    scwin.tabPos = "3";
                    fn_resetClick();
                }
            }
            return false;
        });
    };
    tabs('.tab li');
});




