/*=============================================================================*
 * 날짜컬럼에 포커스들어갈경우 "-" 제거해준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name cal_offMask
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.cal_offMask = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return false;
    }
    eval(sdateVal).setValue("");
    eval(sdateVal).setValue(dateVal.replace(/\-/g, ''));
};


/*=============================================================================*
 * 입력값이 숫자인지를 확인하고 포멧을 만들어준다
 * param : sdateVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name chkDate
 * @description desc
 * @param {string} sdateVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.chkDate = function(sdateVal) {
    var dateVal = eval(sdateVal).getValue();
    if (dateVal.length < 1) {
        return;
    }
    var dateVal2 = scwin.rtnNumber(dateVal);
    window.status = dateVal2.length;
    if (dateVal2.length < 1) {
        eval(sdateVal).setValue("");
    } else if (dateVal2.length >= 1 && dateVal2.length < 8) {
        eval(sdateVal).setValue(dateVal2);
    } else if (dateVal2.length == 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    } else if (dateVal2.length > 8) {
        eval(sdateVal).setValue(dateVal2.substring(0, 4) + "-" + dateVal2.substring(4, 6) + "-" + dateVal2.substring(6, 8));
    }
};



/*=============================================================================*
 * 입력값이 숫자인지를 확인한다
 * param : sVal 입력스트링
 * return : Boolean True이면 숫자값
 *============================================================================*/
/**
 * @method
 * @name rtnNumber
 * @description desc
 * @param {string} sVal desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.rtnNumber = function(sVal) {
    var rtnVal = "";
    if (sVal.length < 1) {
        return rtnVal;
    }
    for (i = 0; i < sVal.length; i++) {
        iBit = parseInt(sVal.substring(i, i + 1)); //문자(Char)를 숫자로 변경
        if (('0' <= iBit) && ('9' >= iBit)) {
            rtnVal = rtnVal + iBit;
        }
    }
    return rtnVal;
};


/*=============================================================================*
 * 일자값 체크 (8문자 수치여부, 년월일값의 범위, 윤년)
 * param : pDate 체크할 날짜
 * return : TRUE or FALSE
 *============================================================================*/
/**
 * @method
 * @name fCheckDate
 * @description desc
 * @param {string} pDate2 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fCheckDate = function(pDate2) {
    // 일자값 저장 배열
    var vDateArray = new Array(3);
    // 값이 없으면 false 리턴
    if (pDate2 == "") {
        return false;
    }
    var pDate = scwin.rtnNumber(pDate2);

    // 값이 없으면 false 리턴
    if (pDate == "") {
        return false;
    }
    // 길이가 8 이 아니면 false 리턴
    if (pDate.length != 8) {
        return false;
    }

    // 길이대로(년:4, 월:2, 일:2) 잘라서 배열에 저장
    vDateArray[0] = pDate.substring(0, 4);
    vDateArray[1] = pDate.substring(4, 6);
    vDateArray[2] = pDate.substring(6, 8);


    // 년도값이 0 부터 9999 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[0]) < 0 || eval(vDateArray[0]) > 9999) {
        return false;
    }

    // 월값이 1 부터 12 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[1]) < 1 || eval(vDateArray[1]) > 12) {
        return false;
    }

    // 일값이 1 부터 31 사이의 수치가 아니면 false 리턴
    if (eval(vDateArray[2]) < 1 || eval(vDateArray[2]) > 31) {
        return false;
    }

    // 월값이 길이가 1 이면 앞에 "0" 을 붙인다
    if (vDateArray[1].length == 1) vDateArray[1] = "0" + vDateArray[1];

    // 일값이 길이가 1 이면 앞에 "0" 을 붙인다
    if (vDateArray[2].length == 1) vDateArray[2] = "0" + vDateArray[1];

    // 30 일까지 있는 달의 일 체크
    if ((eval(vDateArray[1]) == 4 || eval(vDateArray[1]) == 6 || eval(vDateArray[1]) == 9 || eval(vDateArray[1]) == 11) && eval(vDateArray[2]) == 31) {
        return false;
    }

    // 윤년일 경우
    if (((eval(vDateArray[0]) % 4 == 0 && eval(vDateArray[0]) % 100 != 0) || eval(vDateArray[0]) % 400 == 0)) {
        // 2 월의 일 체크
        if (eval(vDateArray[1]) == 2 && eval(vDateArray[2]) > 29) {
            return false;
        }
    }
    // 윤년이 아닐 경우
    else {
        // 2월의 일 체크
        if (eval(vDateArray[1]) == 2 && eval(vDateArray[2]) > 28) {
            return false;
        }
    }
    return true;
};


//text
/**
 * @method
 * @name fn_newTextToString
 * @description desc
 * @param {string} textNew desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_newTextToString = function(textNew) {
    var str = '-- 업로드 파일 정보 시작 --<br/>';
    str += scwin.fn_RPAD('RealFileName', ' ', 20) + ' : {0}<br/>';
    str += scwin.fn_RPAD('ServerFileName', ' ', 20) + ' : {1}<br/>';
    str += scwin.fn_RPAD('Guid', ' ', 20) + ' : {2}<br/>';
    str += scwin.fn_RPAD('Size', ' ', 20) + ' : {3}<br/>';
    str += scwin.fn_RPAD('UploadPath', ' ', 20) + ' : {4}<br/>';
    str += scwin.fn_RPAD('LogicalPath', ' ', 20) + ' : {5}<br/>';
    str += scwin.fn_RPAD('fileExtention', ' ', 20) + ' : {6}<br/>';
    str += scwin.fn_RPAD('LocalPath', ' ', 20) + ' : {7}<br/>';
    str += scwin.fn_RPAD('Mark', ' ', 20) + ' : {8}<br/>';
    str += scwin.fn_RPAD('ResponseCustomValue', ' ', 20) + ' : {9}<br/>';
    str += scwin.fn_RPAD('Order', ' ', 20) + ' : {10}<br/>';
    str += '-- 업로드 파일 정보 끝 --<br/>';
    var originalName = '';
    var uploadName = '';
    var guid = '';
    var size = '';
    var uploadPath = '';
    var logicalPath = '';
    var fileExtension = '';
    var localPath = '';
    var mark = '';
    var responseCustomValue = '';
    var order = '';
    var rtnValue = '';
    var filesArr = textNew.split(scwin.G_vertical);
    var filesArrLen = filesArr.length;
    for (var i = 0; i < filesArrLen; i++) {
        var oneFileAttr = filesArr[i].split(scwin.G_formfeed);
        originalName += oneFileAttr[0];
        uploadPath += oneFileAttr[4];
        if (i != filesArrLen - 1) {
            originalName += scwin.G_formfeed;
            uploadPath += scwin.G_formfeed;
        }
    }
    return originalName + scwin.G_vertical + uploadPath;
};
/**
 * @method
 * @name fn_delTextToString
 * @description desc
 * @param {string} textDel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_delTextToString = function(textDel) {
    var str = '-- 삭제된 파일 정보 --<br/>';
    str += scwin.fn_RPAD('Key', ' ', 8) + ' : {0}<br/>';
    str += scwin.fn_RPAD('FileName', ' ', 8) + ' : {1}<br/>';
    str += scwin.fn_RPAD('Size', ' ', 8) + ' : {2}<br/><br/>';
    var sUniqKey = '';
    var sOriginalName = '';
    var sSize = '';
    var filesArr = textDel.split(scwin.G_vertical);
    var filesArrLen = filesArr.length;
    for (var i = 0; i < filesArrLen; i++) {
        var oneFileAttr = filesArr[i].split(scwin.G_formfeed);
        sUniqKey += oneFileAttr[0];
        sOriginalName += oneFileAttr[1];
        sSize += oneFileAttr[2];
        if (i != filesArrLen - 1) {
            sUniqKey += scwin.G_formfeed;
            sOriginalName += scwin.G_formfeed;
            sSize += ',';
        }
    }
    var rtn = sUniqKey + scwin.G_vertical + sOriginalName;
    return rtn;
};
/**
 * @method
 * @name fn_RPAD
 * @description desc
 * @param {string} s desc
 * @param {string} c desc
 * @param {string} n desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RPAD = function(s, c, n) {
    if (!s || !c || s.length >= n) {
        return s;
    }
    var max = (n - s.length) / c.length;
    for (var i = 0; i < max; i++) {
        s += c;
    }
    return s;
};


/********************************************** 
 * 함수명   : clickTr
 * @param   : tr 제어할 tr 오브젝트
 * 설명     : 테이블 tr 클릭 시 생상변화
 ***********************************************/
/**
 * @method
 * @name clickTr
 * @description desc
 * @param {string} tr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.clickTr = function(tr) {
    $('.table_v').each(function(i) {
        $(this).find('tbody tr').removeClass('point_bgcolor1');
        $(this).find('tbody tr:odd').addClass('bgcolor');
    });
    $(tr).addClass('point_bgcolor1');
};



/********************************************** 
 * 함수명   : clickTr
 * @param   : tr 제어할 tr 오브젝트
 * 설명     : 테이블 tr 클릭 시 생상변화
 ***********************************************/
/**
 * @method
 * @name clickTrById
 * @description desc
 * @param {string} tableId desc
 * @param {string} tr desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.clickTrById = function(tableId, tr) {
    $('#' + tableId + " tr").each(function(i) {
        $(this).removeClass('point_bgcolor1');
        if ($(this).hasClass("odd")) {
            $(this).addClass('bgcolor');
        }
    });
    $(tr).addClass('point_bgcolor1');
};



