 */
scwin.setCommonSelect = function(selectId) {
    var appendOption = "<option value='9'>공통</option>";
    var selectLastVal = $('#' + selectId + ' option:last').val();
    switch (commonAuth) {
        case "B":
            if (selectLastVal == "2") {
                $('#' + selectId).append(appendOption);
            }
            break;
        case "C":
            if (selectLastVal == "2" || selectLastVal == "6") {
                $('#' + selectId).append(appendOption);
            }
            break;
    }
};



